<script lang="ts">
import {onMount} from 'svelte';import {PUBLIC_CONVEX_URL} from '$env/static/public';import {authenticatedClient,functionRef,sessionRequest} from '$lib/admin';
let data:any=$state(null),error=$state(''),signed=$state(false),busy=$state(false),plan=$state('steady'),funding=$state('individual'),amount=$state(100),adult=$state(false),risk=$state(false);let client:any;const money=(n:number)=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format((n??0)/100);
async function run(name:string,args:Record<string,unknown>={}){busy=true;error='';try{await client.mutation(functionRef('investments:'+name),args);}catch(e){error=e instanceof Error?e.message:String(e);}finally{busy=false;}}
onMount(()=>{let off:()=>void;let disposed=false;(async()=>{try{signed=!!(await sessionRequest('/api/auth/session')).user;if(!signed||disposed)return;client=authenticatedClient(PUBLIC_CONVEX_URL);off=client.onUpdate(functionRef('investments:dashboard'),{},(v:any)=>data=v,(e:Error)=>error=e.message);}catch(e){error=String(e);}})();return()=>{disposed=true;off?.();void client?.close();};});
